        val ga = makeSpecialArrowFromFunctionalMethod(gm).get
        lteq(fa, ga)
      case (_,_) =>
        val fa = makeArrowFromFunctional(f, true).get
        val ga = makeArrowFromFunctional(g, true).get
        lteq(fa, ga)
    }
